def weekly_revenue(sales: list[Sale]) -> dict[str, int]:
    weeks = group_by(sales, key=lambda s: iso_week_label(s.paid_at.date()))
    return {w: sum(s.order.total_cents for s in ss) for w, ss in sorted(weeks.items())}

